const rows = $input.all().map(i => i.json);
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const lines = rows.map(r => `<tr><td>${esc(r.platform_name)}</td><td>${esc(r.aspect_name)}</td><td>${esc(r.metric_name)}</td><td>${esc(r.metric_value)}</td><td>${esc(r.threshold)}</td><td>${esc(r.recommended_action ?? '')}</td><td>${esc(r.responsible_department ?? '')}</td><td>${esc(r.detected_at)}</td></tr>`).join('');
const html = `<p>Có <b>${rows.length}</b> cảnh báo mới vượt ngưỡng:</p><table border="1" cellpadding="6" cellspacing="0"><tr><th>Nền tảng</th><th>Khía cạnh</th><th>Chỉ số</th><th>Giá trị</th><th>Ngưỡng</th><th>Đề xuất hành động</th><th>Bộ phận phụ trách</th><th>Phát hiện lúc</th></tr>${lines}</table><p>Xem chi tiết và đánh dấu đã xử lý trên website EduVision BI.</p>`;
return [{ json: { subject: `[EduVision BI] ${rows.length} cảnh báo mới`, html, alert_keys: rows.map(r => r.alert_key) } }];
